539		if _, err := s.CreateCircuit(Circuit{Name: "d", Version: 1, Constraints: 1, Description: "d"}); err != nil {
540			t.Fatal(err)
541		}
542	
543		if _, err := s.CheckInputFile("ghost", 1, a.Hash, badDoc); !errors.Is(err, ErrNotFound) {
544			t.Fatalf("unknown version beats malformed file: %v", err)
545		}
546		if _, err := s.CheckInputFile("d", 1, a.Hash, badDoc); !errors.Is(err, ErrNotFrozen) {
547			t.Fatalf("unfrozen beats malformed file: %v", err)
548		}
