// jvalue is one JSON value as found during the single structural tokenization
// pass. Objects keep their members in document order; raw is the value's own
// byte span within the document (the key text excluded), which the later
// typed reads slice directly instead of re-decoding the surrounding document.
// A null member is represented by kind == jnull; scalar leaves carry their
// json token already decoded (string/number/bool), so scalar type checks need
// no second parse to *decide the type* — only the error text of a rejected
// scalar goes through json.Unmarshal, keeping the diagnostic byte-identical.
type jvalue struct {
	kind    byte // '{', '[', 's' string, 'n' number, 'b' bool, '0' null
	raw     []byte
	str     string
	num     json.Number
	boolean bool
	members []jmember
	items   []*jvalue
}

// jmember is one object value paired with its already-JSON-unescaped key.
type jmember struct {
	key   string
	value *jvalue
}

// parseJValue decodes the complete JSON value the decoder is positioned at,
// tracking the raw span and, for objects, rejecting a repeated member key.
// Keys are compared after JSON unescaping (the decoder already unescapes the
// key token), so a key repeated through a \uXXXX spelling is a duplicate even
// when both values are byte-identical. Every token of the document is visited
// exactly once in this single descent.
func (s jsonShape) parseJValue(dec *json.Decoder, doc []byte, what string) (*jvalue, error) {
	start := dec.InputOffset()
	tok, err := dec.Token()
	if err != nil {
		return nil, s.fail("%s is not valid JSON: %v", what, err)
	}
	switch v := tok.(type) {
	case json.Delim:
		switch v {
		case '{':
			out := &jvalue{kind: '{'}
			seen := make(map[string]bool)
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, s.fail("%s is not valid JSON: %v", what, err)
				}
				key := keyTok.(string)
				if seen[key] {
					return nil, s.fail("%s contains duplicate field %q", what, key)
				}
				seen[key] = true
				child, err := s.parseJValue(dec, doc, what)
				if err != nil {
					return nil, err
				}
				out.members = append(out.members, jmember{key: key, value: child})
			}
			if _, err := dec.Token(); err != nil { // closing brace
				return nil, s.fail("%s is not valid JSON: %v", what, err)
			}
			out.raw = doc[start:dec.InputOffset()]
			return out, nil
		case '[':
			out := &jvalue{kind: '['}
			for dec.More() {
				child, err := s.parseJValue(dec, doc, what)
				if err != nil {
					return nil, err
				}
				out.items = append(out.items, child)
			}
			if _, err := dec.Token(); err != nil { // closing bracket
				return nil, s.fail("%s is not valid JSON: %v", what, err)
			}
			out.raw = doc[start:dec.InputOffset()]
			return out, nil
		}
	case string:
		return &jvalue{kind: 's', raw: doc[start:dec.InputOffset()], str: v}, nil
	case json.Number:
		return &jvalue{kind: 'n', raw: doc[start:dec.InputOffset()], num: v}, nil
	case bool:
		return &jvalue{kind: 'b', raw: doc[start:dec.InputOffset()], boolean: v}, nil
	case nil:
		return &jvalue{kind: '0', raw: doc[start:dec.InputOffset()]}, nil
	}
	return nil, s.fail("%s is not valid JSON", what)
}

// buildDocumentTree validates the document's JSON grammar once — including a
// refusal of trailing data after the single top-level value — and then walks
// the whole value exactly once, returning its tree. The walk is the single
// place a repeated object key is detected at any depth. The what argument
// names the whole document: a duplicate found nested inside a constraint or a
// term is, as before, a document-level finding rather than a per-constraint
// one.
func (s jsonShape) buildDocumentTree(raw []byte, what string) (*jvalue, error) {
	trimmed := bytes.TrimSpace(raw)
	// One grammar pass over the whole document before any shape is judged, so
	// a syntax error or trailing bytes anywhere are reported with encoding/
	// json's own wording, exactly as a direct unmarshal would.
	var head json.RawMessage
	if err := json.Unmarshal(trimmed, &head); err != nil {
		return nil, s.fail("%s is not valid JSON: %v", what, err)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.UseNumber()
	root, err := s.parseJValue(dec, trimmed, what)
	if err != nil {
		return nil, err
	}
	// Reject any token after the top-level value. json.Unmarshal above also
	// rejects trailing data, but for a second complete value ("…}{}") it
	// decodes only the first and succeeds, so the decoder check is what names
	// the extra token.
	if tok, err := dec.Token(); err == nil {
		return nil, s.fail("%s is not valid JSON: invalid character %s after top-level value",
			what, trailingTokenText(tok))
	}
	return root, nil
}

// trailingTokenText renders the first unexpected trailing token the way the
// pre-consolidation unmarshal-based check quoted it in an "invalid character
// %s after top-level value" message: punctuation as itself, the start of a
// string as '"', a digit as its own rune.
func trailingTokenText(tok json.Token) string {
	switch v := tok.(type) {
	case json.Delim:
		return string(v)
	case string:
		return `"`
	case json.Number:
		if len(v) > 0 {
			return string(v[0])
		}
	}
	return ""
}

