// buildDocumentTree validates the document's JSON grammar once — including a
// refusal of trailing data after the single top-level value — and then walks
// the whole value exactly once, returning its tree. The walk is the single
// place a repeated object key is detected at any depth. The what argument
// names the whole document: a duplicate found nested inside a constraint or a
// term is, as before, a document-level finding rather than a per-constraint
// one.
func (s jsonShape) buildDocumentTree(raw []byte, what string) (*jvalue, error) {
	trimmed := bytes.TrimSpace(raw)
	// One grammar pass over the whole document before any shape is judged, so
	// a syntax error or trailing bytes anywhere are reported with encoding/
	// json's own wording, exactly as a direct unmarshal would.
	var head json.RawMessage
	if err := json.Unmarshal(trimmed, &head); err != nil {
		return nil, s.fail("%s is not valid JSON: %v", what, err)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.UseNumber()
	root, err := s.parseJValue(dec, trimmed, what)
	if err != nil {
		return nil, err
	}
