// member's colon and surrounding JSON whitespace. The leading grammar pass
// already proved a colon and value follow, so the scan is exact.
func (b *documentBuilder) valueStartAfterKey() int64 {
	i := b.dec.InputOffset()
	isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' }
	for i < int64(len(b.doc)) && isSpace(b.doc[i]) {
		i++
	}
	if i < int64(len(b.doc)) && b.doc[i] == ':' {
		i++
